"""Skill: take a screenshot of the whole screen."""

import re

from ai.response_generator import ResponseGenerator
from automation.system_control import capture_screenshot
from multitasking.async_executor import run_in_thread
from skills._base import Skill, SkillMatch, SkillResult

_PATTERN = re.compile(
    r"take\s+(a\s+)?screenshot|screenshot|capture\s+(the\s+)?screen"
)


class ScreenshotSkill(Skill):
    name = "screenshot"
    description = "Take a screenshot of the whole screen and save to Desktop"
    priority = 15

    def __init__(self):
        self._responses = ResponseGenerator()

    def match(self, text: str) -> SkillMatch | None:
        if _PATTERN.search(text.lower()):
            return SkillMatch(confidence=0.95)
        return None

    async def run(self, text: str, entities: dict) -> SkillResult:
        ok, path = await run_in_thread(capture_screenshot)
        if ok:
            return SkillResult(text=self._responses.screenshot_taken(path))
        return SkillResult(text=self._responses.action_failed("take screenshot"))
